# Check if a node is a weak cryptographic configuration
check_weak_crypto_node(node) {
    node.ir_type == "String"
    check_weak_algorithm(node)
} else {
    node.ir_type == "String"
    check_weak_protocol(node)
} else {
    node.ir_type == "String"
    check_weak_mode(node)
} else {
    node.ir_type == "Integer"
    check_key_size(node)
} else {
    node.ir_type == "Integer"
    check_iteration_count(node)
}

# Helper to traverse complex values and check for weak crypto
traverse_and_check_weak_crypto(value) {
    walk(value, [_, node])
    check_weak_crypto_node(node)
}

